package com.kicksidepanel;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("kicksidepanel")
public interface KickSidePanelConfig extends Config
{
	@ConfigItem(
		keyName = "channel",
		name = "Kick channel",
		description = "Enter the Kick channel name or URL you want to connect to.",
		position = 1
	)
	default String channel()
	{
		return "";
	}

	@ConfigItem(
		keyName = "autoConnect",
		name = "Auto-connect on login",
		description = "Connect automatically when the client starts.",
		position = 2
	)
	default boolean autoConnect()
	{
		return false;
	}

	@ConfigItem(
		keyName = "colorUsernames",
		name = "Color usernames",
		description = "Show each chatter's name in their Kick color.",
		position = 3
	)
	default boolean colorUsernames()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTimestamps",
		name = "Show timestamps",
		description = "Show the time each message arrived.",
		position = 4
	)
	default boolean showTimestamps()
	{
		return true;
	}

	@ConfigItem(
		keyName = "maxMessages",
		name = "Message history",
		description = "How many messages to keep before older ones scroll off.",
		position = 5
	)
	default int maxMessages()
	{
		return 200;
	}

	@ConfigItem(
		keyName = "textSize",
		name = "Text size",
		description = "Size of incoming chat message text.",
		position = 6
	)
	default TextSize textSize()
	{
		return TextSize.MEDIUM;
	}

	enum TextSize
	{
		SMALL,
		MEDIUM,
		LARGE;

		public float points()
		{
			switch (this)
			{
				case SMALL:
					return 12f;
				case LARGE:
					return 16f;
				default:
					return 14f;
			}
		}

		@Override
		public String toString()
		{
			switch (this)
			{
				case SMALL:
					return "Small";
				case LARGE:
					return "Large";
				default:
					return "Medium";
			}
		}
	}

	// --- Internal state below, not shown in the settings UI. Written directly via
	// ConfigManager.setConfiguration() rather than through this interface. ---

	@ConfigItem(keyName = "accessToken", name = "", description = "", hidden = true)
	default String accessToken()
	{
		return "";
	}

	@ConfigItem(keyName = "refreshToken", name = "", description = "", hidden = true)
	default String refreshToken()
	{
		return "";
	}

	@ConfigItem(keyName = "loggedInUsername", name = "", description = "", hidden = true)
	default String loggedInUsername()
	{
		return "";
	}
}

package com.kicksidepanel;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.kicksidepanel.kick.KickApiClient;
import com.kicksidepanel.kick.KickAuthService;
import com.kicksidepanel.kick.KickChannelName;
import com.kicksidepanel.kick.KickChatClient;
import com.kicksidepanel.kick.KickChatListener;
import com.kicksidepanel.kick.KickMessage;
import com.kicksidepanel.ui.KickPanelIcon;
import com.kicksidepanel.ui.KickSidePanel;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

/**
 * Shows Kick chat in a RuneLite side panel, Party-Hub style, sibling to the Twitch Chat Side
 * Panel plugin. Only ever connects to the single channel set in this plugin's config - there's
 * no in-panel way to switch to a different channel at runtime. Reading chat works anonymously
 * with no login; logging in with Kick (OAuth Authorization Code + PKCE) additionally unlocks
 * sending messages as yourself.
 * <p>
 * See the README for why this looks architecturally different from the sibling Twitch
 * plugin: Kick's official public API has no way to read live chat at all (its only push
 * mechanism is a webhook to a server this plugin can't host), so chat is read over Kick's
 * unofficial Pusher WebSocket feed ({@link KickChatClient}) while everything else - resolving
 * the channel for sending, logging in, and sending messages - goes through Kick's official
 * REST API ({@link KickApiClient}, {@link KickAuthService}).
 */
@PluginDescriptor(
	name = "Kick Chat Side Panel",
	description = "Shows your Kick channel's chat in a side panel",
	tags = {"kick", "chat", "stream", "panel"}
)
public class KickSidePanelPlugin extends Plugin implements KickChatListener
{
	private static final String CONFIG_GROUP = "kicksidepanel";

	// A shared Kick application (Client ID + Secret) baked into the plugin so every user just
	// logs in with their own account with zero setup - same spirit as the Twitch plugin's
	// baked-in Client ID. Unlike Twitch, Kick's token exchange requires a client_secret even
	// for this PKCE flow, so this secret can't be truly confidential in an open-source plugin's
	// public source - see the README for that tradeoff. Registered with redirect URI
	// http://127.0.0.1:17953/callback in Kick's developer settings.
	private static final String CLIENT_ID = "01KXKYAYEMQF94847GVQRM9HCC";
	private static final String CLIENT_SECRET = "b835c92f6138e0ec47c29f8be5c8147763a5ab00a64994613059b5e4dee1607f";

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private KickSidePanelConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executor;

	private KickSidePanel panel;
	private NavigationButton navButton;
	private KickChatClient chatClient;
	private KickApiClient apiClient;
	private KickAuthService authService;

	private volatile Long broadcasterUserId;
	private volatile String resolvedForChannel;

	@Provides
	KickSidePanelConfig getConfig(final ConfigManager configManager)
	{
		return configManager.getConfig(KickSidePanelConfig.class);
	}

	@Override
	protected void startUp()
	{
		apiClient = new KickApiClient(gson);
		chatClient = new KickChatClient(this, gson);
		authService = new KickAuthService(gson, executor);

		panel = new KickSidePanel(new KickSidePanel.Handlers()
		{
			@Override
			public void onConnectClicked()
			{
				connectToChannel();
			}

			@Override
			public void onDisconnectClicked()
			{
				chatClient.disconnect();
				panel.setConnected(false);
				panel.setStatus("Not connected", false);
			}

			@Override
			public void onLoginClicked()
			{
				startLogin();
			}

			@Override
			public void onCancelLoginClicked()
			{
				authService.cancel();
			}

			@Override
			public void onLogoutClicked()
			{
				clearLogin();
				panel.showLoginPrompt();
			}

			@Override
			public void onSendMessage(String text)
			{
				sendMessage(text);
			}
		}, KickChannelName.normalize(config.channel()));

		BufferedImage icon = KickPanelIcon.create();

		navButton = NavigationButton.builder()
			.tooltip("Kick Chat")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		restoreLoginState();

		if (config.autoConnect() && !KickChannelName.normalize(config.channel()).isEmpty())
		{
			connectToChannel();
		}
	}

	@Override
	protected void shutDown()
	{
		authService.cancel();
		if (chatClient != null)
		{
			chatClient.disconnect();
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		panel = null;
	}

	private void connectToChannel()
	{
		String channel = KickChannelName.normalize(config.channel());
		panel.setStatus("Connecting to " + channel + "...", false);

		executor.execute(() ->
		{
			Long chatroomId = apiClient.resolveChatroomId(channel);
			if (panel == null)
			{
				return;
			}
			if (chatroomId == null)
			{
				panel.setStatus("Couldn't find that Kick channel - it may not exist, or Kick is blocking this request", true);
				return;
			}
			chatClient.connect(channel, chatroomId);
		});
	}

	private void startLogin()
	{
		panel.showWaitingForLogin();
		authService.startLogin(CLIENT_ID, CLIENT_SECRET, new KickAuthService.LoginListener()
		{
			@Override
			public void onAuthorized(String accessToken, String refreshToken, String username)
			{
				configManager.setConfiguration(CONFIG_GROUP, "accessToken", accessToken);
				configManager.setConfiguration(CONFIG_GROUP, "refreshToken", refreshToken == null ? "" : refreshToken);
				configManager.setConfiguration(CONFIG_GROUP, "loggedInUsername", username);
				if (panel != null)
				{
					panel.showLoggedIn(username);
				}
			}

			@Override
			public void onError(String message)
			{
				if (panel != null)
				{
					panel.showLoginError(message);
				}
			}
		});
	}

	private void restoreLoginState()
	{
		String accessToken = config.accessToken();
		if (accessToken.isEmpty())
		{
			panel.showLoginPrompt();
			return;
		}

		// Validating blocks on a network call - run it off the startUp() thread so plugin
		// startup itself never stalls waiting on Kick.
		executor.execute(() ->
		{
			String username = authService.fetchUsername(accessToken);
			if (panel == null)
			{
				return;
			}
			if (username != null)
			{
				configManager.setConfiguration(CONFIG_GROUP, "loggedInUsername", username);
				panel.showLoggedIn(username);
			}
			else
			{
				clearLogin();
				panel.showLoginPrompt();
			}
		});
	}

	private void clearLogin()
	{
		configManager.unsetConfiguration(CONFIG_GROUP, "accessToken");
		configManager.unsetConfiguration(CONFIG_GROUP, "refreshToken");
		configManager.unsetConfiguration(CONFIG_GROUP, "loggedInUsername");
	}

	/**
	 * Sends a message via Kick's official REST API. Unlike the Twitch plugin, this never
	 * echoes the message locally - Kick's Pusher feed broadcasts every chat message to every
	 * subscriber of the room, including this plugin's own anonymous read connection, so a
	 * message sent this way is expected to arrive back over {@link #onMessage} the same as
	 * anyone else's, without any special-casing needed here.
	 */
	private void sendMessage(String text)
	{
		String accessToken = config.accessToken();
		String channel = KickChannelName.normalize(config.channel());
		if (accessToken.isEmpty() || channel.isEmpty() || text == null || text.trim().isEmpty())
		{
			return;
		}

		executor.execute(() ->
		{
			Long id = resolveBroadcasterUserId(channel);
			if (id == null)
			{
				if (panel != null)
				{
					panel.appendSystemMessage("Couldn't send - failed to resolve this channel");
				}
				return;
			}

			boolean ok = apiClient.sendMessage(accessToken, id, text.trim());
			if (!ok && panel != null)
			{
				panel.appendSystemMessage("Failed to send message");
			}
		});
	}

	/** Cached per channel - re-resolved if the configured channel has changed since last use. */
	private Long resolveBroadcasterUserId(String channel)
	{
		if (broadcasterUserId != null && channel.equals(resolvedForChannel))
		{
			return broadcasterUserId;
		}
		Long id = apiClient.resolveBroadcasterUserId(CLIENT_ID, CLIENT_SECRET, channel);
		if (id != null)
		{
			broadcasterUserId = id;
			resolvedForChannel = channel;
		}
		return id;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()) || !"channel".equals(event.getKey()))
		{
			return;
		}

		String raw = config.channel();
		String normalized = KickChannelName.normalize(raw);
		if (!normalized.equals(raw))
		{
			configManager.setConfiguration(CONFIG_GROUP, "channel", normalized);
			return;
		}

		if (panel != null)
		{
			panel.setChannel(normalized);
		}
	}

	@Override
	public void onConnected(String channel)
	{
		if (panel == null)
		{
			return;
		}
		panel.setConnected(true);
		panel.setStatus("Connected to " + channel, false);
		panel.appendSystemMessage("Connected to " + channel);
	}

	@Override
	public void onDisconnected(String reason)
	{
		if (panel == null)
		{
			return;
		}
		panel.setConnected(false);
		panel.setStatus(reason, true);
	}

	@Override
	public void onMessage(KickMessage message)
	{
		if (panel == null)
		{
			return;
		}
		panel.appendMessage(message, config.colorUsernames(), config.showTimestamps(), config.maxMessages(),
			config.textSize().points());
	}
}

package com.kicksidepanel.kick;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

/**
 * Talks to Kick's official public REST API (<a href="https://docs.kick.com">docs.kick.com</a>)
 * for everything it actually supports - resolving a channel slug to its
 * {@code broadcaster_user_id} and sending chat messages - plus one unofficial lookup
 * ({@link #resolveChatroomId}) that the official API has no equivalent for at all.
 * <p>
 * Kick's official API has no way to read live chat (the only delivery mechanism for incoming
 * messages is a webhook to a publicly-reachable server, which a desktop plugin can't host),
 * so {@link KickChatClient} reads chat via Kick's unofficial Pusher WebSocket feed instead.
 * That feed is keyed by a numeric "chatroom id" which the official API doesn't expose -
 * {@link #resolveChatroomId} is the one place this class reaches into Kick's unofficial
 * {@code kick.com/api/v2} surface to get it, same as every other open-source Kick chat
 * client does. This is a real reliability risk flagged in this plugin's README: Kick could
 * change or block this endpoint without notice.
 */
public class KickApiClient
{
	private static final String API_BASE = "https://api.kick.com/public/v1";
	private static final String OAUTH_TOKEN_URL = "https://id.kick.com/oauth/token";
	private static final String UNOFFICIAL_CHANNEL_URL = "https://kick.com/api/v2/channels/";
	private static final Duration TIMEOUT = Duration.ofSeconds(10);

	private final HttpClient httpClient = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
	private final Gson gson;

	private volatile String cachedAppToken;
	private volatile long cachedAppTokenExpiresAtMillis;

	/** {@code gson} should be RuneLite's shared, Guice-injected instance - never {@code new Gson()}. */
	public KickApiClient(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Resolves a channel slug to its {@code broadcaster_user_id} via the official API, using
	 * an app access token (Client Credentials grant - no user login required). Needed as the
	 * {@code broadcaster_user_id} argument to {@link #sendMessage}. Returns {@code null} on
	 * any failure.
	 */
	public Long resolveBroadcasterUserId(String clientId, String clientSecret, String slug)
	{
		try
		{
			String appToken = appAccessToken(clientId, clientSecret);
			if (appToken == null)
			{
				return null;
			}

			HttpRequest request = HttpRequest.newBuilder(URI.create(API_BASE + "/channels?slug=" + urlEncode(slug)))
				.header("Authorization", "Bearer " + appToken)
				.timeout(TIMEOUT)
				.GET()
				.build();
			HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
			if (response.statusCode() != 200)
			{
				return null;
			}

			JsonObject json = gson.fromJson(response.body(), JsonObject.class);
			JsonArray data = json.getAsJsonArray("data");
			if (data == null || data.size() == 0)
			{
				return null;
			}
			JsonObject channel = data.get(0).getAsJsonObject();
			return channel.has("broadcaster_user_id") ? channel.get("broadcaster_user_id").getAsLong() : null;
		}
		catch (Exception e)
		{
			// Broad on purpose: callers run this on a background thread and treat null as
			// "couldn't resolve", never letting an unexpected response shape kill the thread.
			return null;
		}
	}

	/**
	 * Resolves a channel slug to the numeric chatroom id {@link KickChatClient} needs to
	 * subscribe to on Kick's Pusher feed, via Kick's unofficial (undocumented, reverse
	 * engineered) {@code kick.com/api/v2/channels/{slug}} endpoint - see the class-level note
	 * on why the official API can't do this. Anonymous, no token needed. Returns {@code null}
	 * on any failure, including Kick blocking the request outright.
	 */
	public Long resolveChatroomId(String slug)
	{
		try
		{
			HttpRequest request = HttpRequest.newBuilder(URI.create(UNOFFICIAL_CHANNEL_URL + urlEncode(slug)))
				// A generic browser-like User-Agent, not to disguise the client as something
				// it isn't, but because this endpoint has been reported to reject requests
				// with no User-Agent at all - see the class-level reliability note.
				.header("User-Agent",
					"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36")
				.header("Accept", "application/json")
				.timeout(TIMEOUT)
				.GET()
				.build();
			HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
			if (response.statusCode() != 200)
			{
				return null;
			}

			JsonObject json = gson.fromJson(response.body(), JsonObject.class);
			JsonObject chatroom = json.getAsJsonObject("chatroom");
			if (chatroom == null || !chatroom.has("id"))
			{
				return null;
			}
			return chatroom.get("id").getAsLong();
		}
		catch (Exception e)
		{
			return null;
		}
	}

	/**
	 * Sends a chat message as the logged-in user via the official API. {@code userAccessToken}
	 * must carry the {@code chat:write} scope. Returns {@code true} on success.
	 */
	public boolean sendMessage(String userAccessToken, long broadcasterUserId, String content)
	{
		try
		{
			JsonObject body = new JsonObject();
			body.addProperty("broadcaster_user_id", broadcasterUserId);
			body.addProperty("content", content);
			body.addProperty("type", "user");

			HttpRequest request = HttpRequest.newBuilder(URI.create(API_BASE + "/chat"))
				.header("Authorization", "Bearer " + userAccessToken)
				.header("Content-Type", "application/json")
				.timeout(TIMEOUT)
				.POST(HttpRequest.BodyPublishers.ofString(gson.toJson(body)))
				.build();
			HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
			return response.statusCode() >= 200 && response.statusCode() < 300;
		}
		catch (Exception e)
		{
			return false;
		}
	}

	/**
	 * Returns a cached app access token, refreshing it via the Client Credentials grant once
	 * it's within a minute of expiring. Thread-safety note: two overlapping refreshes in a
	 * narrow race window would just each fetch their own token and the later write wins -
	 * harmless, since both are valid.
	 */
	private String appAccessToken(String clientId, String clientSecret) throws IOException, InterruptedException
	{
		if (cachedAppToken != null && System.currentTimeMillis() < cachedAppTokenExpiresAtMillis)
		{
			return cachedAppToken;
		}

		String form = "grant_type=client_credentials"
			+ "&client_id=" + urlEncode(clientId)
			+ "&client_secret=" + urlEncode(clientSecret);

		HttpRequest request = HttpRequest.newBuilder(URI.create(OAUTH_TOKEN_URL))
			.header("Content-Type", "application/x-www-form-urlencoded")
			.timeout(TIMEOUT)
			.POST(HttpRequest.BodyPublishers.ofString(form))
			.build();
		HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
		if (response.statusCode() != 200)
		{
			return null;
		}

		JsonObject json = gson.fromJson(response.body(), JsonObject.class);
		String token = json.has("access_token") ? json.get("access_token").getAsString() : null;
		if (token == null)
		{
			return null;
		}

		int expiresInSeconds = json.has("expires_in") ? json.get("expires_in").getAsInt() : 3600;
		cachedAppTokenExpiresAtMillis = System.currentTimeMillis() + Math.max(0, expiresInSeconds - 60) * 1000L;
		cachedAppToken = token;
		return token;
	}

	private static String urlEncode(String value)
	{
		return URLEncoder.encode(value, StandardCharsets.UTF_8);
	}
}

package com.kicksidepanel.kick;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.URLDecoder;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.time.Duration;
import java.util.Base64;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import net.runelite.client.util.LinkBrowser;

/**
 * Logs into Kick using the OAuth 2.1 Authorization Code + PKCE flow - Kick's public API has
 * no device code grant (unlike Twitch's, which the sibling Twitch Chat Side Panel plugin
 * uses), so unlike that plugin this needs a real redirect: a short-lived local HTTP listener
 * on {@code http://127.0.0.1:17953/callback} catches the browser redirect after the user
 * approves the login on kick.com.
 * <p>
 * Unlike Twitch's "Public" client type, Kick's token exchange requires a {@code client_secret}
 * even for this flow (confirmed against Kick's own docs), so this plugin's Client ID/Secret
 * pair (see {@code KickSidePanelPlugin.CLIENT_ID}/{@code CLIENT_SECRET}) is baked in the same
 * way Twitch's Client ID is - it identifies "which app is asking," not any individual user.
 * Unlike a true confidential-client secret, this one can't be kept truly secret in an
 * open-source plugin's public source, which is a real (if fairly standard for this kind of
 * app) tradeoff - see the README.
 * <p>
 * Deliberately never blocks a thread waiting for the browser redirect - the user could take
 * anywhere from seconds to minutes to approve (or never approve) the login, and Plugin Hub
 * review has separately flagged blocking background-thread patterns in the sibling Twitch
 * plugin. Instead, the token exchange and everything after it runs directly inside the local
 * HTTP server's own callback handler once Kick actually redirects back - nothing waits on it
 * in the meantime.
 */
public class KickAuthService
{
	private static final String AUTHORIZE_URL = "https://id.kick.com/oauth/authorize";
	private static final String TOKEN_URL = "https://id.kick.com/oauth/token";
	private static final String USERS_URL = "https://api.kick.com/public/v1/users";
	// user:read is needed for fetchUsername (GET /public/v1/users) - chat:write alone lets
	// the token send messages but not look itself up.
	private static final String SCOPES = "chat:write user:read";
	private static final int CALLBACK_PORT = 17953;
	private static final String REDIRECT_URI = "http://127.0.0.1:" + CALLBACK_PORT + "/callback";

	private final HttpClient httpClient = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final AtomicBoolean cancelled = new AtomicBoolean(false);
	private volatile HttpServer activeServer;

	public interface LoginListener
	{
		void onAuthorized(String accessToken, String refreshToken, String username);

		/** Login failed, expired, or was rejected - never called after {@link #cancel()}. */
		void onError(String message);
	}

	/** {@code gson} should be RuneLite's shared, Guice-injected instance - never {@code new Gson()}. */
	public KickAuthService(Gson gson, ScheduledExecutorService executor)
	{
		this.gson = gson;
		this.executor = executor;
	}

	/**
	 * Starts a login attempt on the client's shared executor: opens the system browser to
	 * Kick's consent page, then returns immediately - the rest of the flow continues inside
	 * {@link #handleCallback} once (and if) Kick actually redirects back. Only one attempt
	 * should be in flight at a time - call {@link #cancel()} first if a previous attempt is
	 * still waiting.
	 */
	public void startLogin(String clientId, String clientSecret, LoginListener listener)
	{
		cancelled.set(false);
		executor.execute(() -> beginLogin(clientId, clientSecret, listener));
	}

	public void cancel()
	{
		cancelled.set(true);
		HttpServer server = activeServer;
		if (server != null)
		{
			server.stop(0);
			activeServer = null;
		}
	}

	/**
	 * Generates this attempt's PKCE material, starts the local callback listener, and opens
	 * the browser - all quick, bounded work, safe to run directly on the shared executor.
	 * Nothing here blocks waiting for the user to actually approve the login.
	 */
	private void beginLogin(String clientId, String clientSecret, LoginListener listener)
	{
		try
		{
			String state = randomUrlSafeString(24);
			String codeVerifier = randomUrlSafeString(64);
			String codeChallenge = pkceChallenge(codeVerifier);

			startCallbackServer(clientId, clientSecret, state, codeVerifier, listener);

			String authorizeUrl = AUTHORIZE_URL
				+ "?response_type=code"
				+ "&client_id=" + urlEncode(clientId)
				+ "&redirect_uri=" + urlEncode(REDIRECT_URI)
				+ "&scope=" + urlEncode(SCOPES)
				+ "&state=" + urlEncode(state)
				+ "&code_challenge=" + urlEncode(codeChallenge)
				+ "&code_challenge_method=S256";
			openInBrowser(authorizeUrl);
		}
		catch (Exception e)
		{
			// Deliberately broad: this runs on the executor with no other safety net, so
			// anything narrower risks the task dying silently on an unexpected failure -
			// "nothing happens" when you click the button, with no error and nothing to
			// debug.
			if (!cancelled.get())
			{
				listener.onError("Login error: " + (e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName()));
			}
		}
	}

	/**
	 * Looks up the username for a fresh or previously-stored access token, or {@code null}
	 * if it's invalid/expired/unreachable.
	 */
	public String fetchUsername(String accessToken)
	{
		try
		{
			HttpRequest request = HttpRequest.newBuilder(URI.create(USERS_URL))
				.header("Authorization", "Bearer " + accessToken)
				.GET()
				.build();
			HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
			if (response.statusCode() != 200)
			{
				return null;
			}
			JsonObject json = gson.fromJson(response.body(), JsonObject.class);
			JsonArray data = json.getAsJsonArray("data");
			if (data == null || data.size() == 0)
			{
				return null;
			}
			JsonObject user = data.get(0).getAsJsonObject();
			if (user.has("name"))
			{
				return user.get("name").getAsString();
			}
			if (user.has("username"))
			{
				return user.get("username").getAsString();
			}
			return null;
		}
		catch (Exception e)
		{
			return null;
		}
	}

	/** Starts a one-shot local HTTP server on {@link #REDIRECT_URI}'s port. */
	private void startCallbackServer(String clientId, String clientSecret, String expectedState, String codeVerifier,
		LoginListener listener) throws IOException
	{
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", CALLBACK_PORT), 0);
		activeServer = server;

		server.createContext("/callback", exchange ->
			handleCallback(exchange, clientId, clientSecret, expectedState, codeVerifier, listener, server));
		server.setExecutor(null);
		server.start();
	}

	/**
	 * Handles Kick's redirect back to this plugin, running on the local HTTP server's own
	 * callback thread - not the shared {@link #executor} - since this is a one-shot,
	 * inherently event-driven piece of work (it only ever runs once per login attempt) rather
	 * than anything resembling a polling loop.
	 */
	private void handleCallback(HttpExchange exchange, String clientId, String clientSecret, String expectedState,
		String codeVerifier, LoginListener listener, HttpServer server) throws IOException
	{
		String code;
		try
		{
			String query = exchange.getRequestURI().getQuery();
			String receivedCode = queryParam(query, "code");
			String state = queryParam(query, "state");
			String error = queryParam(query, "error");

			String responseHtml;
			if (error != null)
			{
				respond(listener, "Kick login was denied (" + error + ")");
				responseHtml = "<html><body>Login cancelled - you can close this tab.</body></html>";
				code = null;
			}
			else if (receivedCode == null || !Objects.equals(state, expectedState))
			{
				respond(listener, "Login response didn't match - try again");
				responseHtml = "<html><body>Something went wrong - you can close this tab and try again.</body></html>";
				code = null;
			}
			else
			{
				responseHtml = "<html><body>Logged in - you can close this tab and return to RuneLite.</body></html>";
				code = receivedCode;
			}

			byte[] bytes = responseHtml.getBytes(StandardCharsets.UTF_8);
			exchange.getResponseHeaders().add("Content-Type", "text/html; charset=utf-8");
			exchange.sendResponseHeaders(200, bytes.length);
			try (OutputStream body = exchange.getResponseBody())
			{
				body.write(bytes);
			}
		}
		finally
		{
			server.stop(0);
			activeServer = null;
		}

		if (code != null)
		{
			exchangeCodeForToken(clientId, clientSecret, code, codeVerifier, listener);
		}
	}

	/**
	 * Exchanges the authorization code for a token and looks up the username - the network
	 * tail end of the login flow, still running on the HTTP server's callback thread (see
	 * {@link #handleCallback}), well after the response to Kick's redirect has already been
	 * sent.
	 */
	private void exchangeCodeForToken(String clientId, String clientSecret, String code, String codeVerifier,
		LoginListener listener)
	{
		if (cancelled.get())
		{
			return;
		}

		try
		{
			HttpResponse<String> tokenResponse = post(TOKEN_URL,
				"grant_type=authorization_code"
					+ "&code=" + urlEncode(code)
					+ "&client_id=" + urlEncode(clientId)
					+ "&client_secret=" + urlEncode(clientSecret)
					+ "&redirect_uri=" + urlEncode(REDIRECT_URI)
					+ "&code_verifier=" + urlEncode(codeVerifier));

			if (tokenResponse.statusCode() != 200)
			{
				respond(listener, "Kick rejected the login (HTTP " + tokenResponse.statusCode() + ")");
				return;
			}

			JsonObject token = gson.fromJson(tokenResponse.body(), JsonObject.class);
			String accessToken = token.get("access_token").getAsString();
			String refreshToken = token.has("refresh_token") ? token.get("refresh_token").getAsString() : null;

			String username = fetchUsername(accessToken);
			if (username == null)
			{
				respond(listener, "Logged in, but couldn't look up your username - try again");
				return;
			}

			if (!cancelled.get())
			{
				listener.onAuthorized(accessToken, refreshToken, username);
			}
		}
		catch (Exception e)
		{
			// Same broad-catch reasoning as beginLogin() - this callback has no other
			// safety net, so an unexpected failure should surface a visible error rather
			// than silently stop.
			respond(listener, "Login error: " + (e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName()));
		}
	}

	private void respond(LoginListener listener, String errorMessage)
	{
		if (!cancelled.get())
		{
			listener.onError(errorMessage);
		}
	}

	private static String queryParam(String query, String key)
	{
		if (query == null)
		{
			return null;
		}
		for (String pair : query.split("&"))
		{
			int eq = pair.indexOf('=');
			if (eq > 0 && pair.substring(0, eq).equals(key))
			{
				return URLDecoder.decode(pair.substring(eq + 1), StandardCharsets.UTF_8);
			}
		}
		return null;
	}

	private void openInBrowser(String uri)
	{
		LinkBrowser.browse(uri);
	}

	private HttpResponse<String> post(String url, String form) throws IOException, InterruptedException
	{
		HttpRequest request = HttpRequest.newBuilder(URI.create(url))
			.header("Content-Type", "application/x-www-form-urlencoded")
			.POST(HttpRequest.BodyPublishers.ofString(form))
			.build();
		return httpClient.send(request, HttpResponse.BodyHandlers.ofString());
	}

	private static String randomUrlSafeString(int numBytes)
	{
		byte[] bytes = new byte[numBytes];
		new SecureRandom().nextBytes(bytes);
		return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
	}

	private static String pkceChallenge(String codeVerifier) throws Exception
	{
		MessageDigest digest = MessageDigest.getInstance("SHA-256");
		byte[] hash = digest.digest(codeVerifier.getBytes(StandardCharsets.US_ASCII));
		return Base64.getUrlEncoder().withoutPadding().encodeToString(hash);
	}

	private static String urlEncode(String value)
	{
		return URLEncoder.encode(value, StandardCharsets.UTF_8);
	}
}

package com.kicksidepanel.kick;

import java.util.Locale;

/**
 * Normalizes whatever gets typed or pasted into the "Kick channel" config field into a plain
 * channel slug - so pasting a full channel URL straight from a browser's address bar (e.g.
 * {@code https://kick.com/somechannel}) works exactly the same as typing the slug itself.
 */
public final class KickChannelName
{
	private KickChannelName()
	{
	}

	public static String normalize(String raw)
	{
		if (raw == null)
		{
			return "";
		}

		String value = raw.trim();
		if (value.isEmpty())
		{
			return "";
		}

		while (value.startsWith("@"))
		{
			value = value.substring(1);
		}

		int kickTv = value.toLowerCase(Locale.ROOT).indexOf("kick.com/");
		if (kickTv >= 0)
		{
			value = value.substring(kickTv + "kick.com/".length());
		}

		// Drop any path/query/fragment after the channel slug itself, e.g. the "/videos" in
		// ".../somechannel/videos" or a "?foo=bar" some share links add.
		value = value.split("[/?#]", 2)[0];

		return value.trim().toLowerCase(Locale.ROOT);
	}
}

package com.kicksidepanel.kick;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.awt.Color;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.WebSocket;
import java.time.Duration;
import java.util.concurrent.CompletionStage;
import java.util.regex.Pattern;

/**
 * Reads Kick chat over Kick's unofficial Pusher WebSocket feed - Kick's official public API
 * has no way to read live chat at all (its only incoming-message mechanism is a webhook to a
 * publicly-reachable server, which a desktop plugin can't host), so every third-party Kick
 * chat client, this one included, connects directly to the same Pusher channel Kick's own
 * web client uses. This is undocumented and could change or break without notice - see the
 * plugin README for the full reliability caveat.
 * <p>
 * Anonymous and read-only by design: Kick's chat feed itself doesn't accept a login on this
 * connection the way Twitch's IRC gateway does, so unlike the Twitch plugin, there is no
 * authenticated variant of this client. Sending messages instead goes through
 * {@link KickApiClient#sendMessage}, Kick's official REST API.
 */
public class KickChatClient
{
	private static final URI PUSHER_ENDPOINT = URI.create(
		"wss://ws-us2.pusher.com/app/32cbd69e4b950bf97679?protocol=7&client=js&version=8.4.0-rc2&flash=false");
	private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(10);

	private final KickChatListener listener;
	private final Gson gson;
	private final HttpClient httpClient = HttpClient.newBuilder()
		.connectTimeout(CONNECT_TIMEOUT)
		.build();

	private volatile WebSocket webSocket;
	private volatile boolean stopRequested;
	private volatile String currentChannel;

	/** {@code gson} should be RuneLite's shared, Guice-injected instance - never {@code new Gson()}. */
	public KickChatClient(KickChatListener listener, Gson gson)
	{
		this.listener = listener;
		this.gson = gson;
	}

	/**
	 * Connects to Kick's Pusher WebSocket and subscribes to {@code chatroomId}'s chat channel.
	 * {@code channelSlug} is only used for the {@link KickChatListener#onConnected} callback,
	 * not the connection itself. Safe to call from the Swing EDT.
	 */
	public void connect(String channelSlug, long chatroomId)
	{
		currentChannel = channelSlug;
		stopRequested = false;

		httpClient.newWebSocketBuilder()
			.connectTimeout(CONNECT_TIMEOUT)
			.buildAsync(PUSHER_ENDPOINT, new PusherListener(channelSlug, chatroomId))
			.exceptionally(error ->
			{
				if (!stopRequested)
				{
					listener.onDisconnected("Connection error: " + rootMessage(error));
				}
				return null;
			});
	}

	public void disconnect()
	{
		stopRequested = true;
		WebSocket ws = webSocket;
		webSocket = null;
		if (ws != null)
		{
			// sendClose() only starts a graceful close handshake - the connection (and
			// incoming messages with it) doesn't actually stop until Pusher acks its own
			// close frame back, which isn't guaranteed to happen promptly. abort() tears
			// down the underlying TCP connection immediately, which is what a user clicking
			// "Disconnect" actually expects.
			ws.abort();
		}
	}

	private class PusherListener implements WebSocket.Listener
	{
		private final String channelSlug;
		private final long chatroomId;
		private final StringBuilder frameBuffer = new StringBuilder();

		PusherListener(String channelSlug, long chatroomId)
		{
			this.channelSlug = channelSlug;
			this.chatroomId = chatroomId;
		}

		@Override
		public void onOpen(WebSocket ws)
		{
			webSocket = ws;
			// Nothing to send here - Pusher's handshake sends pusher:connection_established
			// first, and the actual channel subscription only goes out once that's been
			// seen (see handleEvent below), per the Pusher protocol.
			WebSocket.Listener.super.onOpen(ws);
		}

		@Override
		public CompletionStage<?> onText(WebSocket ws, CharSequence data, boolean last)
		{
			if (stopRequested)
			{
				// A message can already be in flight when disconnect() runs - drop it
				// rather than keep appending to a feed the user just asked to stop.
				return null;
			}

			frameBuffer.append(data);
			if (last)
			{
				String message = frameBuffer.toString();
				frameBuffer.setLength(0);
				handleFrame(ws, message);
			}
			ws.request(1);
			return null;
		}

		@Override
		public void onError(WebSocket ws, Throwable error)
		{
			if (!stopRequested)
			{
				listener.onDisconnected("Connection error: " + rootMessage(error));
			}
		}

		@Override
		public CompletionStage<?> onClose(WebSocket ws, int statusCode, String reason)
		{
			if (!stopRequested)
			{
				listener.onDisconnected(reason == null || reason.isEmpty() ? "Connection closed by Kick" : reason);
			}
			return null;
		}

		private void handleFrame(WebSocket ws, String frame)
		{
			JsonObject envelope;
			try
			{
				envelope = gson.fromJson(frame, JsonObject.class);
			}
			catch (Exception e)
			{
				return;
			}
			if (envelope == null || !envelope.has("event"))
			{
				return;
			}

			String event = envelope.get("event").getAsString();
			switch (event)
			{
				case "pusher:connection_established":
					subscribe(ws, chatroomId);
					break;
				case "pusher:ping":
					ws.sendText("{\"event\":\"pusher:pong\",\"data\":{}}", true);
					break;
				case "pusher_internal:subscription_succeeded":
					listener.onConnected(channelSlug);
					break;
				case "pusher:error":
					if (!stopRequested)
					{
						listener.onDisconnected("Kick rejected the connection: " + envelope.get("data"));
					}
					break;
				case "App\\Events\\ChatMessageEvent":
					handleChatMessage(envelope);
					break;
				default:
					// Kick's Pusher feed also emits sub/gift/follow/ban events on this same
					// channel - not shown by this plugin (see README), so anything else here
					// is deliberately ignored rather than treated as an error.
					break;
			}
		}

		/**
		 * Pusher's own protocol double-encodes: the outer frame's {@code data} field is
		 * itself a JSON string, not a nested object, so it needs a second parse pass.
		 */
		private void handleChatMessage(JsonObject envelope)
		{
			if (!envelope.has("data"))
			{
				return;
			}
			JsonObject data;
			try
			{
				data = gson.fromJson(envelope.get("data").getAsString(), JsonObject.class);
			}
			catch (Exception e)
			{
				return;
			}
			if (data == null || !data.has("content") || !data.has("sender"))
			{
				return;
			}

			JsonObject sender = data.getAsJsonObject("sender");
			String username = sender.has("username") ? sender.get("username").getAsString() : null;
			if (username == null || username.isEmpty())
			{
				return;
			}

			Color color = null;
			if (sender.has("identity") && sender.getAsJsonObject("identity").has("color"))
			{
				color = parseColor(sender.getAsJsonObject("identity").get("color").getAsString());
			}

			String content = stripEmotePlaceholders(data.get("content").getAsString());
			listener.onMessage(new KickMessage(username, content, color, System.currentTimeMillis()));
		}
	}

	// Kick's chat body embeds emote references inline in the message text itself, e.g.
	// "nice one [emote:5838776:odablockShalom]" - unlike Twitch, which reports emote
	// positions in a separate IRC tag and leaves the body as the literal typed text. Since
	// this plugin deliberately never renders emote images (see README), left alone these
	// placeholders would just leak through as raw "[emote:id:name]" noise. Reducing each one
	// to its plain name keeps the message readable as actual plain text instead.
	private static final Pattern EMOTE_PLACEHOLDER = Pattern.compile("\\[emote:\\d+:([^\\]]*)\\]");

	private static String stripEmotePlaceholders(String content)
	{
		return EMOTE_PLACEHOLDER.matcher(content).replaceAll("$1");
	}

	private void subscribe(WebSocket ws, long chatroomId)
	{
		JsonObject subscribe = new JsonObject();
		subscribe.addProperty("event", "pusher:subscribe");
		JsonObject data = new JsonObject();
		data.addProperty("channel", "chatrooms." + chatroomId + ".v2");
		subscribe.add("data", data);
		ws.sendText(gson.toJson(subscribe), true);
	}

	private static Color parseColor(String hex)
	{
		if (hex == null || hex.isEmpty())
		{
			return null;
		}
		try
		{
			return Color.decode(hex);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static String rootMessage(Throwable error)
	{
		Throwable cause = error;
		while (cause.getCause() != null)
		{
			cause = cause.getCause();
		}
		String message = cause.getMessage();
		return message != null ? message : cause.getClass().getSimpleName();
	}
}

package com.kicksidepanel.kick;

/**
 * Callbacks fired by {@link KickChatClient}. All callbacks arrive on the client's own
 * background thread, not the Swing EDT - implementations that touch UI must hop over via
 * SwingUtilities.invokeLater themselves.
 */
public interface KickChatListener
{
	void onConnected(String channel);

	void onDisconnected(String reason);

	void onMessage(KickMessage message);
}

package com.kicksidepanel.kick;

import java.awt.Color;

/**
 * A single parsed Kick chat message, ready for display. No emote/badge image rendering by
 * design - see the plugin's README for why.
 */
public class KickMessage
{
	public final String username;
	public final String body;
	public final Color color;
	public final long receivedAtMillis;

	public KickMessage(String username, String body, Color color, long receivedAtMillis)
	{
		this.username = username;
		this.body = body;
		this.color = color;
		this.receivedAtMillis = receivedAtMillis;
	}
}

package com.kicksidepanel.ui;

import com.kicksidepanel.kick.KickMessage;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.function.Consumer;
import java.util.regex.Pattern;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import javax.swing.JTextPane;
import javax.swing.text.BadLocationException;
import javax.swing.text.SimpleAttributeSet;
import javax.swing.text.StyleConstants;
import javax.swing.text.StyledDocument;

/**
 * A single chat line, flowing as one continuous wrapped paragraph - "Username: message text"
 * all in one JTextPane. Plain text only, deliberately: no emote or badge image rendering (see
 * the plugin README for why). A message that mentions {@code myUsername} is highlighted, and
 * clicking the sender's name starts a reply to that person via {@code onUsernameClicked}.
 */
public class ChatMessageRowPanel extends JPanel
{
	private static final Color DEFAULT_NAME_COLOR = new Color(0x53, 0xfc, 0x18);
	private static final Color BODY_COLOR = new Color(0xef, 0xef, 0xf1);
	private static final Color TIME_COLOR = new Color(0x6d, 0x6d, 0x78);
	private static final Color MENTION_BACKGROUND = new Color(0x1d, 0x3a, 0x14);
	private static final Color MENTION_BORDER = new Color(0x53, 0xfc, 0x18);
	private static final SimpleDateFormat TIME_FORMAT = new SimpleDateFormat("HH:mm");

	public ChatMessageRowPanel(KickMessage message, boolean colorUsernames, boolean showTimestamp,
		float fontSize, String myUsername, Consumer<String> onUsernameClicked)
	{
		setLayout(new BorderLayout());
		setAlignmentX(LEFT_ALIGNMENT);

		if (mentionsUser(message.body, myUsername))
		{
			setOpaque(true);
			setBackground(MENTION_BACKGROUND);
			setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 3, 0, 0, MENTION_BORDER),
				BorderFactory.createEmptyBorder(2, 7, 2, 10)));
		}
		else
		{
			setOpaque(false);
			setBorder(BorderFactory.createEmptyBorder(2, 10, 2, 10));
		}

		JTextPane pane = buildLine(message, colorUsernames, showTimestamp, fontSize, onUsernameClicked);
		add(pane, BorderLayout.CENTER);
	}

	/**
	 * A plain JPanel inside a BoxLayout column defaults to an unbounded maximum height, so
	 * with only a few short messages in a tall scroll panel, BoxLayout was distributing all
	 * the empty leftover vertical space into the rows themselves instead of leaving it blank
	 * at the bottom. Tying the maximum height to the current preferred height stops that.
	 */
	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	/**
	 * True if {@code body} mentions {@code username} as a whole word, with or without a
	 * leading "@".
	 */
	private static boolean mentionsUser(String body, String username)
	{
		if (username == null || username.isEmpty())
		{
			return false;
		}
		String pattern = "(?i)(?<![A-Za-z0-9_])@?" + Pattern.quote(username) + "(?![A-Za-z0-9_])";
		return Pattern.compile(pattern).matcher(body).find();
	}

	private JTextPane buildLine(KickMessage message, boolean colorUsernames, boolean showTimestamp,
		float fontSize, Consumer<String> onUsernameClicked)
	{
		JTextPane pane = new JTextPane();
		pane.setEditable(false);
		pane.setOpaque(false);
		pane.setBorder(null);
		pane.setFont(pane.getFont().deriveFont(fontSize));

		StyledDocument doc = pane.getStyledDocument();

		SimpleAttributeSet timeStyle = new SimpleAttributeSet();
		StyleConstants.setForeground(timeStyle, TIME_COLOR);

		SimpleAttributeSet nameStyle = new SimpleAttributeSet();
		StyleConstants.setForeground(nameStyle, colorUsernames && message.color != null ? message.color : DEFAULT_NAME_COLOR);
		StyleConstants.setBold(nameStyle, true);

		SimpleAttributeSet bodyStyle = new SimpleAttributeSet();
		StyleConstants.setForeground(bodyStyle, BODY_COLOR);

		int nameStart = -1;
		int nameEnd = -1;

		try
		{
			if (showTimestamp)
			{
				doc.insertString(doc.getLength(), TIME_FORMAT.format(new Date(message.receivedAtMillis)) + "  ", timeStyle);
			}

			nameStart = doc.getLength();
			doc.insertString(doc.getLength(), message.username + ": ", nameStyle);
			nameEnd = nameStart + message.username.length();

			doc.insertString(doc.getLength(), message.body, bodyStyle);
		}
		catch (BadLocationException e)
		{
			// Only possible if our own offset bookkeeping above is wrong; fall back to the
			// raw, un-styled message rather than showing nothing.
			pane.setText(message.username + ": " + message.body);
		}

		addUsernameClickHandling(pane, nameStart, nameEnd, message.username, onUsernameClicked);

		return pane;
	}

	/**
	 * Lets clicking the sender's name (the "Username" in "Username: message") start a reply
	 * to them, the same click-a-name-to-@mention gesture Kick's own chat offers.
	 */
	private void addUsernameClickHandling(JTextPane pane, int nameStart, int nameEnd, String username,
		Consumer<String> onUsernameClicked)
	{
		if (nameStart < 0)
		{
			return;
		}

		pane.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (isOverName(pane, e, nameStart, nameEnd))
				{
					onUsernameClicked.accept(username);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				pane.setCursor(Cursor.getDefaultCursor());
			}
		});

		pane.addMouseMotionListener(new MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				pane.setCursor(Cursor.getPredefinedCursor(
					isOverName(pane, e, nameStart, nameEnd) ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
			}
		});
	}

	private static boolean isOverName(JTextPane pane, MouseEvent e, int nameStart, int nameEnd)
	{
		int offset = pane.viewToModel2D(e.getPoint());
		return offset >= nameStart && offset < nameEnd;
	}
}

package com.kicksidepanel.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * The sidebar navigation icon, drawn in code rather than shipped as a bundled PNG - a simple
 * green chat bubble with a "K" is enough to distinguish this panel in the toolbar.
 */
public final class KickPanelIcon
{
	private KickPanelIcon()
	{
	}

	public static BufferedImage create()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		g.setColor(new Color(0x53, 0xfc, 0x18));
		g.fillRoundRect(0, 0, 16, 12, 4, 4);
		g.fillPolygon(new int[]{4, 8, 4}, new int[]{12, 12, 16}, 3);

		g.setColor(Color.BLACK);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 9));
		g.drawString("K", 5, 10);

		g.dispose();
		return image;
	}
}

package com.kicksidepanel.ui;

import com.kicksidepanel.kick.KickMessage;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/**
 * Side panel that shows Kick chat as a scrolling message feed, styled to match Kick's own
 * chat window as closely as a Swing side panel reasonably can, Party-Hub style. Only ever
 * connects to the single channel configured in the plugin's settings - there is no free-text
 * field or other way to switch to a different channel from the panel itself.
 * <p>
 * Reading chat works with no login. Logging in with Kick (OAuth Authorization Code + PKCE)
 * additionally unlocks sending messages.
 */
public class KickSidePanel extends PluginPanel
{
	public interface Handlers
	{
		void onConnectClicked();

		void onDisconnectClicked();

		void onLoginClicked();

		void onCancelLoginClicked();

		void onLogoutClicked();

		void onSendMessage(String text);
	}

	private enum AuthState
	{
		LOGGED_OUT,
		WAITING_FOR_LOGIN,
		LOGGED_IN
	}

	private static final Color BACKGROUND = new Color(0x0e, 0x0e, 0x12);
	private static final Color TAB_BAR_BACKGROUND = new Color(0x17, 0x17, 0x1d);
	private static final Color DIVIDER = new Color(0x26, 0x26, 0x2e);
	private static final Color MUTED_TEXT = new Color(0x8a, 0x8a, 0x95);
	private static final Color ACCENT = new Color(0x53, 0xfc, 0x18);
	private static final Color ACCENT_HOVER = new Color(0x74, 0xfd, 0x47);
	private static final Color ACCENT_TEXT = Color.BLACK;

	private final JLabel channelLabel;
	private final OpenChannelButton openChannelButton;
	private final PillButton connectButton;
	private final JLabel statusLabel;
	private final JLabel authStatusLabel;
	private final PillButton authButton;
	private final JPanel messageListPanel;
	private final JScrollPane scrollPane;
	private final PlaceholderTextField messageField;
	private final PillButton sendButton;
	private final JPanel sendRow;

	private final Handlers handlers;
	private boolean connected;
	private boolean channelConfigured;
	private AuthState authState = AuthState.LOGGED_OUT;
	private volatile String myUsername;
	private volatile String currentChannel = "";

	private static final int MAX_RECENT_USERNAMES = 300;
	private final List<String> recentUsernames = new ArrayList<>();

	public KickSidePanel(Handlers handlers, String channel)
	{
		// PluginPanel's default (no-arg) constructor wraps all content in its own
		// DynamicGridLayout + JScrollPane machinery, which conflicts with our own
		// BorderLayout + JScrollPane below. super(false) opts out of that.
		super(false);

		this.handlers = handlers;

		setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
		setBackground(BACKGROUND);
		setLayout(new BorderLayout());

		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(BACKGROUND);
		header.setBorder(BorderFactory.createEmptyBorder(10, 10, 8, 10));

		JLabel title = new JLabel("Kick Chat");
		title.setForeground(Color.WHITE);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
		title.setAlignmentX(LEFT_ALIGNMENT);

		JPanel connectRow = new JPanel(new BorderLayout(6, 0));
		connectRow.setBackground(BACKGROUND);
		connectRow.setAlignmentX(LEFT_ALIGNMENT);
		connectRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		connectRow.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));

		channelLabel = new JLabel();
		channelLabel.setForeground(MUTED_TEXT);

		openChannelButton = new OpenChannelButton(BACKGROUND);
		openChannelButton.addActionListener(e -> openChannelInBrowser());

		JPanel channelNameRow = new JPanel(new BorderLayout(2, 0));
		channelNameRow.setOpaque(false);
		channelNameRow.add(channelLabel, BorderLayout.CENTER);
		channelNameRow.add(openChannelButton, BorderLayout.EAST);

		connectButton = new PillButton("Connect", ACCENT, ACCENT_HOVER);
		connectButton.setForeground(ACCENT_TEXT);
		connectButton.addActionListener(e -> handleConnectButton());

		connectRow.add(channelNameRow, BorderLayout.CENTER);
		connectRow.add(connectButton, BorderLayout.EAST);

		statusLabel = new JLabel("Not connected");
		statusLabel.setForeground(MUTED_TEXT);
		statusLabel.setFont(statusLabel.getFont().deriveFont(11f));
		statusLabel.setAlignmentX(LEFT_ALIGNMENT);
		statusLabel.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));

		JPanel authRow = new JPanel(new BorderLayout(6, 0));
		authRow.setBackground(BACKGROUND);
		authRow.setAlignmentX(LEFT_ALIGNMENT);
		authRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		authRow.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));

		authStatusLabel = new JLabel("Not logged in");
		authStatusLabel.setForeground(MUTED_TEXT);
		authStatusLabel.setFont(authStatusLabel.getFont().deriveFont(11f));

		authButton = new PillButton("Log in with Kick", new Color(0x2f, 0xa8, 0x0e), new Color(0x3c, 0xc2, 0x18));
		authButton.addActionListener(e -> handleAuthButton());

		authRow.add(authStatusLabel, BorderLayout.CENTER);
		authRow.add(authButton, BorderLayout.EAST);

		header.add(title);
		header.add(connectRow);
		header.add(statusLabel);
		header.add(authRow);

		JPanel tabBar = new JPanel(new BorderLayout());
		tabBar.setBackground(TAB_BAR_BACKGROUND);
		tabBar.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 0, 1, 0, DIVIDER),
			BorderFactory.createEmptyBorder(6, 0, 6, 0)));
		JLabel tabLabel = new JLabel("STREAM CHAT", SwingConstants.CENTER);
		tabLabel.setForeground(MUTED_TEXT);
		tabLabel.setFont(tabLabel.getFont().deriveFont(Font.BOLD, 11f));
		tabBar.add(tabLabel, BorderLayout.CENTER);

		JPanel topContainer = new JPanel();
		topContainer.setLayout(new BoxLayout(topContainer, BoxLayout.Y_AXIS));
		topContainer.setBackground(BACKGROUND);
		topContainer.add(header);
		topContainer.add(tabBar);

		messageListPanel = new ScrollableMessagePanel();
		messageListPanel.setLayout(new BoxLayout(messageListPanel, BoxLayout.Y_AXIS));
		messageListPanel.setBackground(BACKGROUND);
		messageListPanel.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));
		messageListPanel.add(Box.createVerticalGlue());

		scrollPane = new JScrollPane(messageListPanel);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getViewport().setBackground(BACKGROUND);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);

		sendRow = new JPanel(new BorderLayout(8, 0));
		sendRow.setBackground(BACKGROUND);
		sendRow.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 0, 0, 0, DIVIDER),
			BorderFactory.createEmptyBorder(8, 10, 10, 10)));
		sendRow.setVisible(false);

		Color fieldBackground = new Color(0x1e, 0x1e, 0x26);

		messageField = new PlaceholderTextField("Message");
		messageField.setBackground(fieldBackground);
		messageField.setForeground(Color.WHITE);
		messageField.setCaretColor(Color.WHITE);
		messageField.setBorder(BorderFactory.createEmptyBorder());
		messageField.setMargin(new java.awt.Insets(6, 10, 6, 10));
		messageField.addActionListener(e -> handleSend());
		new MentionAutocomplete(messageField, () -> recentUsernames);

		sendButton = new PillButton("Chat", ACCENT, ACCENT_HOVER);
		sendButton.setForeground(ACCENT_TEXT);
		sendButton.addActionListener(e -> handleSend());

		sendRow.add(messageField, BorderLayout.CENTER);
		sendRow.add(sendButton, BorderLayout.EAST);

		add(topContainer, BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);
		add(sendRow, BorderLayout.SOUTH);

		setChannel(channel);
		setConnected(false);
	}

	private void handleConnectButton()
	{
		if (connected)
		{
			handlers.onDisconnectClicked();
		}
		else if (channelConfigured)
		{
			handlers.onConnectClicked();
		}
	}

	private void handleAuthButton()
	{
		switch (authState)
		{
			case LOGGED_OUT:
				handlers.onLoginClicked();
				break;
			case WAITING_FOR_LOGIN:
				handlers.onCancelLoginClicked();
				showLoginPrompt();
				break;
			case LOGGED_IN:
				handlers.onLogoutClicked();
				break;
		}
	}

	private void handleSend()
	{
		String text = messageField.getText();
		if (text != null && !text.trim().isEmpty())
		{
			handlers.onSendMessage(text);
			messageField.setText("");
		}
	}

	/**
	 * Updates the channel this panel will connect to (read from plugin config - there is no
	 * in-panel way to type a different one). Safe to call again later if the user edits the
	 * config while the panel is open.
	 */
	public void setChannel(String channel)
	{
		SwingUtilities.invokeLater(() ->
		{
			currentChannel = channel == null ? "" : channel.trim();
			channelConfigured = !currentChannel.isEmpty();
			channelLabel.setText(channelConfigured ? currentChannel : "No channel set");
			connectButton.setEnabled(channelConfigured || connected);
			openChannelButton.setEnabled(channelConfigured);
			if (!channelConfigured)
			{
				setStatus("Set your channel in the plugin settings", true);
			}
		});
	}

	private void openChannelInBrowser()
	{
		String channel = currentChannel;
		if (channel.isEmpty())
		{
			return;
		}

		LinkBrowser.browse("https://kick.com/" + channel);
	}

	public void setConnected(boolean connected)
	{
		SwingUtilities.invokeLater(() ->
		{
			this.connected = connected;
			connectButton.setText(connected ? "Disconnect" : "Connect");
			connectButton.setEnabled(connected || channelConfigured);
			updateSendRowEnabled();
		});
	}

	public void setStatus(String text, boolean isError)
	{
		SwingUtilities.invokeLater(() ->
		{
			statusLabel.setText(text);
			statusLabel.setForeground(isError ? new Color(0xff, 0x6b, 0x6b) : MUTED_TEXT);
		});
	}

	/** Not logged in, no login attempt in progress. */
	public void showLoginPrompt()
	{
		SwingUtilities.invokeLater(() ->
		{
			authState = AuthState.LOGGED_OUT;
			authStatusLabel.setForeground(MUTED_TEXT);
			authStatusLabel.setText("Not logged in");
			authButton.setText("Log in with Kick");
			sendRow.setVisible(false);
			myUsername = null;
		});
	}

	/** Waiting for the user to approve the login in their browser. */
	public void showWaitingForLogin()
	{
		SwingUtilities.invokeLater(() ->
		{
			authState = AuthState.WAITING_FOR_LOGIN;
			authStatusLabel.setForeground(MUTED_TEXT);
			authStatusLabel.setText("Approve the login in your browser...");
			authButton.setText("Cancel");
		});
	}

	public void showLoginError(String message)
	{
		SwingUtilities.invokeLater(() ->
		{
			authState = AuthState.LOGGED_OUT;
			authStatusLabel.setForeground(new Color(0xff, 0x6b, 0x6b));
			authStatusLabel.setText(message);
			authButton.setText("Log in with Kick");
			sendRow.setVisible(false);
			myUsername = null;
		});
	}

	public void showLoggedIn(String username)
	{
		SwingUtilities.invokeLater(() ->
		{
			authState = AuthState.LOGGED_IN;
			authStatusLabel.setForeground(MUTED_TEXT);
			authStatusLabel.setText("Logged in as " + username);
			authButton.setText("Log out");
			myUsername = username;
			updateSendRowEnabled();
		});
	}

	private void updateSendRowEnabled()
	{
		sendRow.setVisible(authState == AuthState.LOGGED_IN);
		messageField.setEnabled(connected);
		sendButton.setEnabled(connected);
	}

	public void appendMessage(KickMessage message, boolean colorUsernames, boolean showTimestamps, int maxMessages,
		float fontSize)
	{
		SwingUtilities.invokeLater(() ->
		{
			recordUsername(message.username);

			ChatMessageRowPanel row = new ChatMessageRowPanel(message, colorUsernames, showTimestamps,
				fontSize, myUsername, this::startReplyTo);
			insertRow(row);

			while (messageListPanel.getComponentCount() - 1 > maxMessages)
			{
				messageListPanel.remove(0);
			}

			messageListPanel.revalidate();
			messageListPanel.repaint();
			scrollPane.validate();
			scrollPane.getVerticalScrollBar().setValue(scrollPane.getVerticalScrollBar().getMaximum());
		});
	}

	/**
	 * Appends a plugin-generated notice - e.g. "Connected to channel" - styled distinctly
	 * from a real chat message.
	 */
	public void appendSystemMessage(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			insertRow(new SystemMessageRowPanel(text));
			messageListPanel.revalidate();
			messageListPanel.repaint();
			scrollPane.validate();
			scrollPane.getVerticalScrollBar().setValue(scrollPane.getVerticalScrollBar().getMaximum());
		});
	}

	/** The trailing glue component must stay last, so insert new rows just before it. */
	private void insertRow(Component row)
	{
		messageListPanel.add(row, messageListPanel.getComponentCount() - 1);
	}

	public void clearMessages()
	{
		SwingUtilities.invokeLater(() ->
		{
			messageListPanel.removeAll();
			messageListPanel.add(Box.createVerticalGlue());
			messageListPanel.revalidate();
			messageListPanel.repaint();
		});
	}

	private void recordUsername(String username)
	{
		recentUsernames.removeIf(existing -> existing.equalsIgnoreCase(username));
		recentUsernames.add(0, username);
		if (recentUsernames.size() > MAX_RECENT_USERNAMES)
		{
			recentUsernames.remove(recentUsernames.size() - 1);
		}
	}

	private void startReplyTo(String username)
	{
		String text = "@" + username + " ";
		messageField.setText(text);
		messageField.requestFocusInWindow();
		messageField.setCaretPosition(text.length());
	}

	/**
	 * A plain JPanel doesn't implement {@link Scrollable}, so a JScrollPane's viewport never
	 * forces its width to match the viewport - it's left free to grow as wide as its widest
	 * child wants. Tracking the viewport's width here gives each row's JTextPane a real
	 * bounded width to wrap its text against.
	 */
	private static class ScrollableMessagePanel extends JPanel implements Scrollable
	{
		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}
	}
}

package com.kicksidepanel.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Rectangle;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.DefaultListCellRenderer;
import javax.swing.DefaultListModel;
import javax.swing.JList;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/**
 * Watches a text field for an in-progress "@partialname" and pops up a filtered list of
 * recently-seen chatters to complete it from - the same "@" mention autocomplete Kick's own
 * chat input offers. Wires itself to the field entirely through listeners; nothing else needs
 * to hold a reference to this once constructed.
 */
final class MentionAutocomplete
{
	private static final Color BACKGROUND = new Color(0x17, 0x17, 0x1d);
	private static final Color BORDER = new Color(0x33, 0x33, 0x3d);
	private static final Color SELECTED = new Color(0x2f, 0xa8, 0x0e);
	private static final int MAX_SUGGESTIONS = 8;
	private static final int ROW_HEIGHT = 22;

	private final JTextField field;
	private final Supplier<List<String>> recentUsernamesSupplier;
	private final JPopupMenu popup = new JPopupMenu();
	private final DefaultListModel<String> listModel = new DefaultListModel<>();
	private final JList<String> list = new JList<>(listModel);

	private int mentionStart = -1;

	MentionAutocomplete(JTextField field, Supplier<List<String>> recentUsernamesSupplier)
	{
		this.field = field;
		this.recentUsernamesSupplier = recentUsernamesSupplier;

		list.setBackground(BACKGROUND);
		list.setForeground(Color.WHITE);
		list.setSelectionBackground(SELECTED);
		list.setSelectionForeground(Color.WHITE);
		list.setFont(list.getFont().deriveFont(12f));
		list.setFixedCellHeight(ROW_HEIGHT);
		list.setCellRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> l, Object value, int index, boolean isSelected,
				boolean cellHasFocus)
			{
				super.getListCellRendererComponent(l, "@" + value, index, isSelected, cellHasFocus);
				setOpaque(true);
				setBackground(isSelected ? SELECTED : BACKGROUND);
				setForeground(Color.WHITE);
				setBorder(BorderFactory.createEmptyBorder(2, 8, 2, 8));
				return this;
			}
		});
		list.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				int index = list.locationToIndex(e.getPoint());
				if (index >= 0)
				{
					applySelection(index);
				}
			}
		});

		JScrollPane scrollPane = new JScrollPane(list);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);

		popup.setBorder(BorderFactory.createLineBorder(BORDER));
		popup.setBackground(BACKGROUND);
		popup.add(scrollPane);
		popup.setFocusable(false);

		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				SwingUtilities.invokeLater(MentionAutocomplete.this::onTextChanged);
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				SwingUtilities.invokeLater(MentionAutocomplete.this::onTextChanged);
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
			}
		});

		field.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				if (!popup.isVisible())
				{
					return;
				}
				switch (e.getKeyCode())
				{
					case KeyEvent.VK_DOWN:
						moveSelection(1);
						e.consume();
						break;
					case KeyEvent.VK_UP:
						moveSelection(-1);
						e.consume();
						break;
					case KeyEvent.VK_ENTER:
					case KeyEvent.VK_TAB:
						if (list.getSelectedIndex() >= 0)
						{
							applySelection(list.getSelectedIndex());
							e.consume();
						}
						break;
					case KeyEvent.VK_ESCAPE:
						hide();
						e.consume();
						break;
					default:
						break;
				}
			}
		});
	}

	private void moveSelection(int delta)
	{
		int size = listModel.size();
		if (size == 0)
		{
			return;
		}
		int next = Math.max(0, Math.min(size - 1, list.getSelectedIndex() + delta));
		list.setSelectedIndex(next);
		list.ensureIndexIsVisible(next);
	}

	private void onTextChanged()
	{
		String text = field.getText();
		int caret = field.getCaretPosition();
		int at = findMentionStart(text, caret);
		if (at < 0)
		{
			hide();
			return;
		}

		String query = text.substring(at + 1, caret);
		List<String> matches = new ArrayList<>();
		for (String name : recentUsernamesSupplier.get())
		{
			if (name.regionMatches(true, 0, query, 0, query.length()))
			{
				matches.add(name);
				if (matches.size() >= MAX_SUGGESTIONS)
				{
					break;
				}
			}
		}

		if (matches.isEmpty())
		{
			hide();
			return;
		}

		mentionStart = at;
		listModel.clear();
		for (String match : matches)
		{
			listModel.addElement(match);
		}
		list.setSelectedIndex(0);
		list.setVisibleRowCount(matches.size());

		if (!popup.isVisible())
		{
			showBelowCaret(caret);
		}
	}

	private void showBelowCaret(int caret)
	{
		try
		{
			Rectangle caretBounds = field.modelToView2D(caret).getBounds();
			int height = list.getVisibleRowCount() * ROW_HEIGHT + 4;
			popup.show(field, caretBounds.x, -height - 4);
		}
		catch (Exception ignored)
		{
			// Falls back to just not showing rather than crashing on a caret-geometry
			// edge case (e.g. the field isn't showing yet).
		}
	}

	private static int findMentionStart(String text, int caret)
	{
		for (int i = caret - 1; i >= 0; i--)
		{
			char c = text.charAt(i);
			if (c == '@')
			{
				return i;
			}
			if (Character.isWhitespace(c))
			{
				return -1;
			}
		}
		return -1;
	}

	private void applySelection(int index)
	{
		String username = listModel.get(index);
		String text = field.getText();
		int caret = field.getCaretPosition();
		String before = text.substring(0, mentionStart);
		String after = caret <= text.length() ? text.substring(caret) : "";
		String replacement = "@" + username + " ";

		hide();
		field.setText(before + replacement + after);
		field.setCaretPosition(before.length() + replacement.length());
		field.requestFocusInWindow();
	}

	private void hide()
	{
		mentionStart = -1;
		if (popup.isVisible())
		{
			popup.setVisible(false);
		}
	}
}

package com.kicksidepanel.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JButton;

/**
 * Small icon-only button (an external-link glyph) that opens the configured channel's Kick
 * page in the system browser. Drawn directly in code rather than shipping a bundled image
 * asset, same approach as {@link KickPanelIcon}. Stays opaque with a manually painted
 * background matching its surroundings rather than using setContentAreaFilled(false) +
 * setOpaque(false) - that combination renders as literally nothing under RuneLite's runtime
 * LAF (see the same note on {@link PillButton}).
 */
public class OpenChannelButton extends JButton
{
	private static final Color ICON_COLOR = new Color(0x8a, 0x8a, 0x95);
	private static final Color ICON_HOVER_COLOR = Color.WHITE;

	private final Color background;

	public OpenChannelButton(Color background)
	{
		this.background = background;
		setOpaque(true);
		setContentAreaFilled(true);
		setFocusPainted(false);
		setBorderPainted(false);
		setPreferredSize(new Dimension(20, 20));
		setToolTipText("Open channel in browser");
		setCursor(Cursor.getDefaultCursor());
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		g2.setColor(background);
		g2.fillRect(0, 0, getWidth(), getHeight());

		g2.setColor(getModel().isRollover() ? ICON_HOVER_COLOR : ICON_COLOR);
		g2.setStroke(new BasicStroke(1.3f));

		int size = 9;
		int x = (getWidth() - size) / 2;
		int y = (getHeight() - size) / 2 + 1;

		g2.drawRect(x, y + 2, size - 2, size - 2);
		g2.drawLine(x + 3, y + size - 3, x + size, y);
		g2.drawLine(x + size - 3, y, x + size, y);
		g2.drawLine(x + size, y, x + size, y + 3);

		g2.dispose();
	}
}

package com.kicksidepanel.ui;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JButton;

/**
 * A rounded-pill button. Must stay opaque (do NOT setContentAreaFilled(false) +
 * setOpaque(false)) - under RuneLite's runtime LAF that combination renders as literally
 * nothing, even though this same custom-paint approach works fine.
 */
public class PillButton extends JButton
{
	private static final Color DISABLED_OVERLAY = new Color(0x0e, 0x0e, 0x12, 140);

	private final Color background;
	private final Color hoverBackground;

	public PillButton(String text, Color background, Color hoverBackground)
	{
		super(text);
		this.background = background;
		this.hoverBackground = hoverBackground;
		setOpaque(true);
		setContentAreaFilled(true);
		setFocusPainted(false);
		setBorderPainted(false);
		setForeground(Color.WHITE);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		g2.setColor(getModel().isRollover() ? hoverBackground : background);
		g2.fillRoundRect(0, 0, getWidth(), getHeight(), getHeight(), getHeight());
		if (!isEnabled())
		{
			g2.setColor(DISABLED_OVERLAY);
			g2.fillRoundRect(0, 0, getWidth(), getHeight(), getHeight(), getHeight());
		}

		g2.setColor(getForeground());
		g2.setFont(getFont());
		FontMetrics metrics = g2.getFontMetrics();
		String text = getText();
		int x = (getWidth() - metrics.stringWidth(text)) / 2;
		int y = (getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
		g2.drawString(text, x, y);

		g2.dispose();
	}
}

package com.kicksidepanel.ui;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import javax.swing.JTextField;

/**
 * A JTextField that shows gray hint text when empty and unfocused - Swing has no native
 * placeholder-text support, so this paints it directly rather than pulling in a UI kit.
 */
public class PlaceholderTextField extends JTextField
{
	private final String placeholder;

	public PlaceholderTextField(String placeholder)
	{
		this.placeholder = placeholder;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (!getText().isEmpty())
		{
			return;
		}

		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(new Color(0x8a, 0x8a, 0x95));
		g2.setFont(getFont());

		Insets margin = getMargin();
		g2.setClip(margin.left, 0, Math.max(0, getWidth() - margin.left - margin.right), getHeight());

		int textY = (getHeight() - g2.getFontMetrics().getHeight()) / 2 + g2.getFontMetrics().getAscent();
		g2.drawString(placeholder, margin.left, textY);
		g2.dispose();
	}
}

package com.kicksidepanel.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

/**
 * A plugin-generated notice row in the message feed - e.g. "Connected to #channel" - styled
 * distinctly from real chat messages (centered, muted, italic, no sender) so it reads as a
 * system line rather than something someone said in chat.
 */
class SystemMessageRowPanel extends JPanel
{
	private static final Color TEXT_COLOR = new Color(0x6d, 0x6d, 0x78);

	SystemMessageRowPanel(String text)
	{
		setOpaque(false);
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(4, 10, 4, 10));
		setAlignmentX(LEFT_ALIGNMENT);

		JLabel label = new JLabel(text, SwingConstants.CENTER);
		label.setForeground(TEXT_COLOR);
		label.setFont(label.getFont().deriveFont(Font.ITALIC, 11f));
		add(label, BorderLayout.CENTER);
	}

	/** Same unbounded-maximum-height fix as {@link ChatMessageRowPanel} - see its javadoc. */
	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}
}

